<?php
require __DIR__.'/db.php';require_admin();require __DIR__.'/layout.php';require __DIR__.'/user-invite-lib.php';ensure_user_invite_schema($pdo);
function active_admin_count($pdo){return (int)$pdo->query("SELECT COUNT(*) FROM mp_users WHERE role='admin' AND is_active=1")->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$id=isset($_POST['id'])?(int)$_POST['id']:0;try{if($action==='resend'&&$id){$st=$pdo->prepare('SELECT * FROM mp_users WHERE id=?');$st->execute(array($id));$u=$st->fetch();if(!$u)throw new Exception('Uživatel neexistuje.');if(empty($u['email']))throw new Exception('Uživatel nemá vyplněný e-mail.');$token=create_invitation($pdo,$id);$sent=send_user_invitation($u['email'],$u['username'],(string)$u['display_name'],$token);redirect_to('users.php?resent=1&mail='.($sent?'1':'0'));}if($action==='delete'&&$id){$st=$pdo->prepare('SELECT * FROM mp_users WHERE id=?');$st->execute(array($id));$u=$st->fetch();if(!$u)throw new Exception('Uživatel neexistuje.');if((int)$u['id']===(int)$_SESSION['user_id'])throw new Exception('Přihlášený účet nelze smazat.');if($u['role']==='admin'&&(int)$u['is_active']===1&&active_admin_count($pdo)<=1)throw new Exception('Posledního aktivního administrátora nelze smazat.');$pdo->prepare('DELETE FROM mp_users WHERE id=?')->execute(array($id));redirect_to('users.php?deleted=1');}if($action==='toggle'&&$id){$st=$pdo->prepare('SELECT * FROM mp_users WHERE id=?');$st->execute(array($id));$u=$st->fetch();if(!$u)throw new Exception('Uživatel neexistuje.');$new=((int)$u['is_active']===1)?0:1;if((int)$u['id']===(int)$_SESSION['user_id']&&!$new)throw new Exception('Přihlášený účet nelze deaktivovat.');if($u['role']==='admin'&&!$new&&active_admin_count($pdo)<=1)throw new Exception('Posledního aktivního administrátora nelze deaktivovat.');$pdo->prepare('UPDATE mp_users SET is_active=? WHERE id=?')->execute(array($new,$id));redirect_to('users.php?changed=1');}}catch(Exception $e){$_SESSION['user_admin_error']=$e->getMessage();redirect_to('users.php');}}
$rows=$pdo->query('SELECT * FROM mp_users ORDER BY display_name,username')->fetchAll();$error=$_SESSION['user_admin_error']??'';unset($_SESSION['user_admin_error']);page_top('Uživatelé','users');?>
<div class="pagehead"><div><h1>Uživatelé</h1><div class="sub">Účty a oprávnění pro přístup do aplikace.</div></div><a class="btn" href="user-form.php">+ Nový uživatel</a></div><?php if($error): ?><div class="notice error"><?php echo h($error); ?></div><?php endif; ?><?php if(isset($_GET['saved'])): ?><div class="notice">Uživatel byl uložen.</div><?php endif; ?><?php if(isset($_GET['invited'])): ?><div class="notice"><?php echo ($_GET['mail']??'')==='1'?'Uživatel byl vytvořen a pozvánka byla odeslána.':'Uživatel byl vytvořen, ale server nepotvrdil odeslání e-mailu. Pozvánku můžete poslat znovu.'; ?></div><?php endif; ?><?php if(isset($_GET['resent'])): ?><div class="notice"><?php echo ($_GET['mail']??'')==='1'?'Nová pozvánka byla odeslána.':'Server nepotvrdil odeslání e-mailu.'; ?></div><?php endif; ?><?php if(isset($_GET['deleted'])): ?><div class="notice">Uživatel byl smazán.</div><?php endif; ?><?php if(isset($_GET['changed'])): ?><div class="notice">Stav uživatele byl změněn.</div><?php endif; ?><section class="card"><?php foreach($rows as $r): ?><div class="item user-admin-item"><div class="name"><?php echo h($r['display_name']?$r['display_name']:$r['username']); ?> <?php if((int)$r['id']===(int)$_SESSION['user_id']): ?><span class="badge">vy</span><?php endif; ?></div><div class="meta">@<?php echo h($r['username']); ?><?php if(!empty($r['email'])): ?> · <?php echo h($r['email']); ?><?php endif; ?> · <?php echo $r['role']==='admin'?'Administrátor':'Uživatel'; ?> · <?php echo !empty($r['invite_token_hash'])?'Čeká na registraci':((int)$r['is_active']===1?'Aktivní':'Neaktivní'); ?><?php if($r['last_login_at']): ?> · poslední přihlášení <?php echo h($r['last_login_at']); ?><?php endif; ?></div><div class="actions"><a class="btn secondary" href="user-form.php?id=<?php echo (int)$r['id']; ?>">Upravit / heslo</a><?php if(!empty($r['invite_token_hash'])&&!empty($r['email'])): ?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><input type="hidden" name="action" value="resend"><button class="btn secondary" type="submit">Poslat pozvánku znovu</button></form><?php endif; ?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><input type="hidden" name="action" value="toggle"><button class="btn secondary" type="submit"><?php echo (int)$r['is_active']===1?'Deaktivovat':'Aktivovat'; ?></button></form><form method="post" style="display:inline" onsubmit="return confirm('Opravdu smazat tohoto uživatele?');"><input type="hidden" name="csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><input type="hidden" name="action" value="delete"><button class="btn danger" type="submit">Smazat</button></form></div></div><?php endforeach; ?></section><?php page_bottom(); ?>